    function syncSwitch(lang) {
        var label = document.getElementById('langToggleLabel');
        if (label) label.textContent = (lang === 'en') ? 'EN' : 'SW';
        // [L10N 2026-11-23] the language <select> of the sign-in dialog showed "Swahili" while the app was in English
        document.querySelectorAll('select[onchange*="skhSetLang"]').forEach(function (s) { if (s.value !== lang) s.value = lang; });
        document.querySelectorAll('.lang-dropdown-opt').forEach(function (b) {
            var on = b.getAttribute('data-lang') === lang;
            b.classList.toggle('active', on);
            var chk = b.querySelector('.lang-check');
            if (chk) chk.style.visibility = on ? 'visible' : 'hidden';
        });
    }

    function closeLangDropdown() {
        var dd = document.getElementById('langDropdown');
        var btn = document.getElementById('langToggleBtn');
        if (dd) dd.style.display = 'none';
        if (btn) { btn.setAttribute('aria-expanded', 'false'); btn.classList.remove('open'); }
    }

    // [LUGHA 2026-09] Button moja inafungua/funga dropdown ya options.
    window.skhToggleLangDropdown = function (e) {
        if (e && e.stopPropagation) e.stopPropagation();
        var dd = document.getElementById('langDropdown');
        var btn = document.getElementById('langToggleBtn');
        if (!dd) return;
        // [R21] mobile: hamisha menu juu ya body (sticky-top stacking context haifutii bottom-nav)
        if (!dd.dataset.topLevel && window.innerWidth <= 900) { document.body.appendChild(dd); dd.dataset.topLevel = '1'; }
        var open = dd.style.display !== 'none';
        dd.style.display = open ? 'none' : 'block';
        if (btn) {
            btn.setAttribute('aria-expanded', open ? 'false' : 'true');
            btn.classList.toggle('open', !open);
        }
    };
    // Funga dropdown ukigusa sehemu nyingine yoyote.
    document.addEventListener('click', function (e) {
        var wrap = document.getElementById('langSwitchWrap');
        var dd = document.getElementById('langDropdown');
        if (dd && wrap && !wrap.contains(e.target) && !dd.contains(e.target)) closeLangDropdown();
    });
    // Funga dropdown kwa kitufe cha ESC.
    document.addEventListener('keydown', function (e) {
        if (e && e.key === 'Escape') closeLangDropdown();
    });

    // data-i18n-label / data-i18n-title (kwa optgroup/label/title attributes ambazo LMS.apply haishughulikii)
    function applyLabels() {
        document.querySelectorAll('[data-i18n-label]').forEach(function (el) {
            var key = el.getAttribute('data-i18n-label');
            if (key && window.t) el.setAttribute('label', window.t(key));
        });
        document.querySelectorAll('[data-i18n-title]').forEach(function (el) {
            var key = el.getAttribute('data-i18n-title');
            if (key && window.t) el.setAttribute('title', window.t(key));
        });
        // [JOB 25 · R6t] aria-label (vitufe vya ikoni-pekee kama Post)
        document.querySelectorAll('[data-i18n-aria]').forEach(function (el) {
            var key = el.getAttribute('data-i18n-aria');
            if (key && window.t) el.setAttribute('aria-label', window.t(key));
        });
    }

    // [LUGHA 2026-09] Inafafanuliwa mara moja (sio ndani ya boot) ili swichi
    // ifanye kazi hata kabla SokoHaiLMS hajapakia kikamilifu.
    window.skhSetLang = function (lang) {
        if (lang !== 'sw' && lang !== 'en') lang = 'sw';
        window.__skhPendingLang = lang;
        var LMS = window.SokoHaiLMS;
        if (LMS) {
            window.setSokoHaiLanguage(lang);
            applyLabels();
            syncSwitch(lang);
        } else {
            // LMS bado hajapakia: hifadhi chaguo na rekebisha label moja kwa moja.
            try { skh.localStorage.setItem('sokohai_language', lang); } catch (e) {}
            syncSwitch(lang);
        }
        closeLangDropdown();
    };

    // [I18N 2026-11-23] Account sync (Spark-safe: one client write to the owner's own users/{uid}.language, allowed by the
    // existing rules — `language` is not a privileged key). The device choice (localStorage) stays the fallback for guests and
    // offline use. At sign-in the account value wins once, so a second phone opens in the same language. No Cloud Functions.
    (function () {
        var _set = window.skhSetLang, applying = false;
        function uid() { try { return window.skh && window.skh.currentUser && window.skh.currentUser.uid; } catch (e) { return null; } }
        function save(lang) {
            var u = uid(); if (!u || !window.skh || !window.skh.updateDoc || !window.skh.doc || !window.skh.db) return;
            try { if (window.skh.currentUserData && window.skh.currentUserData.language === lang) return; } catch (e) {}
            try { window.skh.updateDoc(window.skh.doc(window.skh.db, 'users', u), { language: lang }).then(function () { try { if (window.skh.currentUserData) window.skh.currentUserData.language = lang; } catch (e) {} }).catch(function () {}); } catch (e) {}
        }
        window.skhSetLang = function (lang) { var r = _set.apply(this, arguments); if (!applying && (lang === 'sw' || lang === 'en')) save(lang); return r; };
        function pull() {
            var u = uid(); if (!u || !window.skh || !window.skh.getDoc || !window.skh.doc) return;
            window.skh.getDoc(window.skh.doc(window.skh.db, 'users', u)).then(function (snap) {
                var v = snap && snap.exists && snap.exists() ? (snap.data() || {}).language : null;
                var cur = (window.SokoHaiLMS && window.SokoHaiLMS.lang) || (function () { try { return skh.localStorage.getItem('sokohai_language'); } catch (e) { return null; } })();
                if ((v === 'sw' || v === 'en') && v !== cur) { applying = true; try { window.skhSetLang(v); } finally { applying = false; } }
            }).catch(function () {});
        }
        document.addEventListener('skh:auth-ready', function (e) { if (e && e.detail && e.detail.user) setTimeout(pull, 600); });
        window.skhLanguageAccountSync = { save: save, pull: pull };
    })();


